SELECT LAST_INSERT_ID()
INSERT INTO b_marketing_task ( `api_code`, `batch_number`, `file_name`, `strategy_id`, `frequency`, `create_time`, `update_time`, `monitor_status`, `status`, `task_number`, `actual_number`, `strategy_name`, `close_date`, `start_date`, `cus_batch`, `monitor_type`, `is_repair`, `context_id`
,`task_type`
,`product_info`
,`cycle_day`
) VALUES ( #{apiCode}, #{batchNumber}, #{fileName}, #{strategyId}, #{frequency}, now(), now(), #{monitorStatus}, #{status}, #{taskNumber}, #{actualNumber}, #{strategyName}, #{closeDate}, #{startDate}, #{cusBatch}, #{monitorType}, #{isRepair}, #{contextId}
,#{taskType}
,#{productInfo}
,#{cycleDay}
);

