mapper.select:
select * from(select shf.api_code, shf.show_title as cusBatchNumber, mt.batch_number as batchNumber, shf.statistic_file_path as statisticFilePath, shf.id as fileId, DATE_FORMAT(shf.create_time,'%Y-%m-%d %H:%i:%s') as scoreBeginTime, GROUP_CONCAT(distinct msp.product_name order by msp.product_name)as productName, shf.actual_num as actualNum, GROUP_CONCAT(distinct mtut.user_type order by mtut.user_type)as userType from stra_his_file as shf left join b_marketing_strategy_product as msp on shf.id = msp.file_id and msp.is_del=1 left join b_marketing_task as mt on mt.api_code = shf.api_code and mt.batch_number = shf.batch_number left join b_marketing_task_extend as mte on mt.id = mte.task_id left join b_marketing_task_user_type as mtut on mtut.batch_number = mt.batch_number and mtut.api_code = mt.api_code where mt.api_code = #{apiCode}
and msp.product_version =#{productVersion}
and mte.upload_time >= #{uploadBeginTime} and mte.upload_time <= #{uploadEndTime}
and
( shf.create_time>= #{item.scoreBeginTime} and shf.create_time<= #{item.scoreEndTime} )
and mtut.user_type in(
#{item}
)
and shf.score_status = 2 and mt.status != 0 group by batchNumber order by shf.create_time desc) vie where api_code = #{apiCode}
find_in_set (#{item},productName)

select sum(actualNum),api_code from(select shf.api_code, shf.show_title as cusBatchNumber, mt.batch_number as batchNumber, shf.statistic_file_path as statisticFilePath, shf.id as fileId, DATE_FORMAT(shf.create_time,'%Y-%m-%d %H:%i:%s') as scoreBeginTime, GROUP_CONCAT(distinct msp.product_name order by msp.product_name)as productName, shf.actual_num as actualNum, GROUP_CONCAT(distinct mtut.user_type order by mtut.user_type)as userType from stra_his_file as shf left join b_marketing_strategy_product as msp on shf.id = msp.file_id and msp.is_del=1 left join b_marketing_task as mt on mt.api_code = shf.api_code and mt.batch_number = shf.batch_number left join b_marketing_task_extend as mte on mt.id = mte.task_id left join b_marketing_task_user_type as mtut on mtut.batch_number = mt.batch_number and mtut.api_code = mt.api_code where mt.api_code = #{apiCode}
and msp.product_version =#{productVersion}
and mte.upload_time >= #{uploadBeginTime} and mte.upload_time <= #{uploadEndTime}
and
( shf.create_time>= #{item.scoreBeginTime} and shf.create_time<= #{item.scoreEndTime} )
and mtut.user_type in(
#{item}
)
and shf.score_status = 2 and mt.status != 0 group by batchNumber order by shf.id desc) vie where api_code = #{apiCode}
find_in_set (#{item},productName)

select *
from b_marketing_task
where   start_date <= #{date} and close_date >=#{date} 

      and id = #{taskId}


       and start_time<=#{hm}  

and status = 1
order by priority, start_time asc

select bmt.id, shf.id as `hisFileId`, bmt.api_code , bmt.batch_number as `batchNumber`, bsrc.id as `ruleId`, bsrc.rule_name as `ruleName`, bsrc.rule_name_short as `ruleNumber`, bmc.cid, bmc.short_name as `cName`, bmt.status, bmt.priority, bmt.task_number as `taskNumber`, bsrc.condition_info as `conditionInfo`, shf.zipFile_name as `fileName`, bmte.condition_type as `conditionType`, bmte.condition_info_show as `conditionInfoShow`, bmte.label_name as `labelName`, bmt.monitor_type as `execType`, shf.create_time as `taskCreateTime`, shf.running_end_time as `taskUpdateTime`, bmt.is_online as `isOnline`, case when shf.status is null then 0 when shf.status = 2 then 2 when shf.status = 0 then 3 when shf.status = 1 then 1 when shf.status = 3 then 1 when shf.status = 4 then 1 when shf.status = 5 then 1 when shf.status = 6 then 1 when shf.status = 7 then 1 when shf.status = 9 then 1 when shf.status = 10 then 4 when shf.status = 11 then 5 when shf.status = 12 then 1 else shf.status end as taskStatus, bmt.start_date as startDate, bmt.close_date as closeDate, bmt.start_time as startTime, bmt.create_time as createTime, bmt.update_time as updateTime
from b_marketing_task bmt
left join stra_his_file shf on shf.batch_number = bmt.batch_number
left join b_marketing_task_extend bmte on bmte.task_id = bmt.id
left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id
left join b_marketing_customer bmc on bmc.api_code = bmt.api_code
where bsrc.is_del = 1 and bmt.status !=0 and bmc.status =1
and bmt.status = #{status}
and (bmt.api_code like concat("%", #{search},"%") or bmc.cid like concat("%", #{search},"%") or bmc.short_name like concat("%", #{search},"%"))
and bmt.create_time >=#{createTimeStart}
and bmt.create_time <#{createTimeEnd}
and bmt.update_time >=#{updateTimeStart}
and bmt.update_time <#{updateTimeEnd}
and shf.status is null
and shf.status = 2
and shf.status in(1,3,4,5,6,7,9,12)
and shf.status =0
and shf.status =10
and shf.status =11
and bmt.id = #{id}
and bmt.monitor_type = #{execType}
order by bmt.create_time desc,bmt.id desc

select status
from stra_his_file
where id = #{hisFileId}

select * from(select shf.api_code, shf.show_title as cusBatchNumber, mt.batch_number as batchNumber, shf.statistic_file_path as statisticFilePath, shf.id as fileId, DATE_FORMAT(shf.create_time,'%Y-%m-%d %H:%i:%s') as scoreBeginTime, GROUP_CONCAT(distinct msp.product_name order by msp.product_name)as productName, shf.actual_num as actualNum, GROUP_CONCAT(distinct mtut.user_type order by mtut.user_type)as userType from stra_his_file as shf left join b_marketing_strategy_product as msp on shf.id = msp.file_id and msp.is_del=1 left join b_marketing_task as mt on mt.api_code = shf.api_code and mt.batch_number = shf.batch_number left join b_marketing_task_extend as mte on mt.id = mte.task_id left join b_marketing_task_user_type as mtut on mtut.batch_number = mt.batch_number and mtut.api_code = mt.api_code left join b_score_doris_log as sdl on sdl.batch_number = shf.batch_number where
mt.api_code =
#{item}
mt.api_code in(
#{item}
)
1=1
and
( shf.create_time>= #{item.scoreBeginTime} and shf.create_time<= #{item.scoreEndTime} )
and mtut.user_type =
#{item}
and mtut.user_type in(
#{item}
)
and shf.score_status = 2 and mt.status != 0 and sdl.status = 2 group by mt.api_code,batchNumber order by mt.api_code,shf.create_time desc) vie

select bmt.id, shf.id as `hisFileId`, bmt.api_code , bmt.batch_number as `batchNumber`, bmt.create_time as createTime, bmt.update_time as updateTime from b_marketing_task bmt left join stra_his_file shf on shf.batch_number = bmt.batch_number left join b_marketing_task_extend bmte on bmte.task_id = bmt.id left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id where bsrc.is_del = 1 and bmt.status = 1 and bmt.monitor_type = 4
and bmt.api_code = #{apiCode}
and shf.status = #{taskStatus}
and bmte.condition_type = #{conditionType}
and bsrc.rule_name_short = #{ruleNameShort}
and bmt.create_time >=#{createTimeStart}
and bmt.create_time <#{createTimeEnd}
order by bmt.create_time desc,bmt.id desc

select bmt.id, shf.id as `hisFileId`, bmt.api_code, bmt.batch_number as `batchNumber`, bmt.status, bmt.priority, bmt.task_number as `taskNumber`, shf.zipFile_name as `fileName`, bmt.monitor_type as `execType`, shf.create_time as `taskCreateTime`, shf.running_end_time as `taskUpdateTime`, bmt.is_online as `isOnline`, case when shf.status is null then 0 when shf.status = 2 then 2 when shf.status = 0 then 3 when shf.status = 1 then 1 when shf.status = 3 then 1 when shf.status = 4 then 1 when shf.status = 5 then 1 when shf.status = 6 then 1 when shf.status = 7 then 1 when shf.status = 9 then 1 when shf.status = 10 then 4 when shf.status = 11 then 5 else shf.status end as taskStatus, bmt.start_date as startDate, bmt.close_date as closeDate, bmt.start_time as startTime, bmt.create_time as createTime, bmt.update_time as updateTime from b_marketing_task bmt left join stra_his_file shf on shf.batch_number = bmt.batch_number where bmt.api_code = #{apiCode} and bmt.status = 1 and bmt.monitor_type != 2 and shf.status = 2
and bmt.batch_number = #{batchNumber}
order by bmt.create_time desc limit 1

select bmt.id, shf.id as `hisFileId`, bmt.api_code , bmt.batch_number as `batchNumber`, bmt.create_time as createTime, bmt.update_time as updateTime, bmte.data_condition as dataCondition from b_marketing_task bmt left join stra_his_file shf on shf.batch_number = bmt.batch_number left join b_marketing_task_extend bmte on bmte.task_id = bmt.id left join b_score_rule_config bsrc on bsrc.id = bmte.rule_id where bsrc.is_del = 1 and bmt.status !=0 and (shf.status is null or shf.status!=2)
and bmt.api_code = #{apiCode}
and bmt.create_time >=#{createTimeStart}
and bmt.create_time <#{createTimeEnd}
order by bmt.create_time desc,bmt.id desc
